func (m StreamItem) Validate() error {
	var errs []Violation
	if (m.Offset < -integerCap || m.Offset > integerCap) {
		errs = append(errs, Violation{"offset", "exceeds ±(2^53-1) integer cap"})
	}
	if len(errs) > 0 {
		return &ValidationError{Violations: errs}
	}
	return nil
}

// UnmarshalJSON parses data into m and validates it, returning a
// *ValidationError listing any violations.
func (m *StreamItem) UnmarshalJSON(data []byte) error {
	var all map[string]json.RawMessage
	if err := json.Unmarshal(data, &all); err != nil {
		return err
	}
	var errs []Violation
	for k := range all {
		switch k {
		case "topic", "data", "offset":
		default:
			errs = append(errs, Violation{k, "unknown field"})
		}
	}
	get := func(k string) *json.RawMessage {
		if v, ok := all[k]; ok {
			return &v
		}
		return nil
	}
	_ = get
	if v, ok := parseStringField(get("topic"), "topic", true, false, &errs); ok {
		m.Topic = v
	}
	if v, ok := parseStringField(get("data"), "data", true, false, &errs); ok {
		m.Data = v
	}
	if v, ok := parseIntegerField(get("offset"), "offset", true, false, &errs); ok {
		m.Offset = v
	}
	if len(errs) > 0 {
		return &ValidationError{Violations: errs}
	}
	return nil
}

// MarshalJSON validates m, then serializes it to JSON, returning a
// *ValidationError if validation fails.
func (m StreamItem) MarshalJSON() ([]byte, error) {
	var errs []Violation
	addViolations(&errs, m.Validate())
	out := map[string]json.RawMessage{}
	marshalField(out, "topic", m.Topic, &errs)
	marshalField(out, "data", m.Data, &errs)
	marshalField(out, "offset", m.Offset, &errs)
	if len(errs) > 0 {
		return nil, &ValidationError{Violations: errs}
	}
	return json.Marshal(out)
}


